  FT["PH-H9256"] = {"id":"PH-H9256","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10808_2016.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将南甘马粦省 Goa 市镇 Payatan 描笼涯的 Payatan 中学改设为名为 Payatan 国立中学的国立中学并为其拨款","en":"An Act Converting the Payatan High School in Barangay Payatan, Municipal of Goa, Province of Camarines Sur Into a National High School to Be Known as Payatan National High School and Appropriating Funds Therefor","orig":"An Act Converting the Payatan High School in Barangay Payatan, Municipal of Goa, Province of Camarines Sur Into a National High School to Be Known as Payatan National High School and Appropriating Funds Therefor","vi":"Đạo luật chuyển đổi Payatan High School thành Payatan National High School","th":"พระราชบัญญัติเปลี่ยนสถานะ Payatan High School เป็น Payatan National High School","id":"Undang-Undang mengubah Payatan High School menjadi Payatan National High School","ms":"Akta menukar Payatan High School kepada Payatan National High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10808","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10808_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9256-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Conversion into a National High School. — The Payatan High School in Barangay Payatan, Municipality of Goa, Province of Camarines Sur is hereby converted into a national high school to be known as Payatan National High School."}},{"id":"PH-H9256-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities — All personnel, assets, liabilities and records of the Payatan High School are hereby transferred to and absorbed by the Payatan National High School."}},{"id":"PH-H9256-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. — The Secretary of Education shall immediately include in the Department's program the operationalization of the Payatan National High School, the initial funding of which shall be charged against the current year's appropriations of the Payatan High School. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H9256-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. — The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H9256-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. — This Act shall take effect fifteen(15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Payatan High School in Barangay Payatan, Municipal of Goa, Province of Camarines Sur Into a National High School to Be Known as Payatan National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9257"] = {"id":"PH-H9257","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10809_2016.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Dupax Del Norte市","en":"An Act Converting Into An Independent National High School to Be Known as the Dupax Del Norte National High School the Dupax Del Norte National High School - Poblacion Annex in Barangay Poblacion of Malasin, Municipality of Dupax Del Norte, Province of Nueva Vizcaya, and Separating It From Its Mother School, the Dupax Dela Norte National High School in Barangay Lamo, Municipality of Dupax Del Norte, Province of Nueva Vizcaya, Hereinafter Renamed the Lamo National High School, Repealing for the Purpose Republic Act No. 9779 and Appropriating Funds Therefor","orig":"An Act Converting Into An Independent National High School to Be Known as the Dupax Del Norte National High School the Dupax Del Norte National High School - Poblacion Annex in Barangay Poblacion of Malasin, Municipality of Dupax Del Norte, Province of Nueva Vizcaya, and Separating It From Its Mother School, the Dupax Dela Norte National High School in Barangay Lamo, Municipality of Dupax Del Norte, Province of Nueva Vizcaya, Hereinafter Renamed the Lamo National High School, Repealing for the Purpose Republic Act No. 9779 and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10809","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10809_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9257-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Dupax del Norte National High School - Poblacion Annex in Barangay Poblacion of Malasin, Municipality of Dupax del Norte, Province of Nueva Vizcaya is hereby converted into an independent national high school to be now known as the Dupax del Norte National High School, and separated from its mother school, the Dupax del Norte National High School situated in Barangay Lamo, Municipality of Dupax del Norte, Province of Nueva Vizcaya.\nThe mother school situated in Barangay Lamo, Municipality of Dupax del Norte, Province of Nueva Vizcaya shall henceforth be known as the Lamo National High School."}},{"id":"PH-H9257-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, assets, liabilities and records of the Dupax del Norte National High School - Poblacion Annex in Barangay Poblacion of Malasin, Municipality of Dupex del Norte, Province of Nueva Vizcaya are hereby transferred to and absorbed by the newly converted national high school, now known as the Dupax del Norte National High School."}},{"id":"PH-H9257-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department's program the operationalization of the newly converted national high school, now known as the Dupax del Norte National High School. The current year's appropriation of the mother school situated in Barangay Lamo, Municipality of Dupax del Norte, Province of Nueva Vizcaya shall be absorbed by and remain with the now renamed Lamo National High School. Thereafter, the amount necessary for the continued operation of both the Dupax del Norte National High School and the Lamo National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H9257-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Republic Act No. 9779, entitled \"An Act Changing the Name of Lamo National High School in Barangay Lamo, Municipality of Dupax del Norte, Province of Nueva Vizcaya to Dupax del Norte National High School\", is hereby repealed."}},{"id":"PH-H9257-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132"};
  FT["PH-H9258"] = {"id":"PH-H9258","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10810_2016.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将巴拉望省Bataraza市镇Malihud描笼涯的Tarusan国立中学Malihud延伸校从Tarusan国立中学分离，改设为独立的Malihud国立中学并为此拨款的法案","en":"An Act Separating the Tarusan National High School - Malihud Extension in Barangay Malihud, Municipality of Bataraza, Province of Palawan From the Tarusan National High School, Converting It Into An Independent National High School to Be Known as Malihud National High School and Appropriating Funds Therefor","orig":"An Act Separating the Tarusan National High School - Malihud Extension in Barangay Malihud, Municipality of Bataraza, Province of Palawan From the Tarusan National High School, Converting It Into An Independent National High School to Be Known as Malihud National High School and Appropriating Funds Therefor","vi":"Đạo luật tách Phân hiệu Malihud của Trường Trung học Tarusan Quốc gia tại Barangay Malihud, Đô thị Bataraza, Tỉnh Palawan khỏi Trường Trung học Tarusan Quốc gia và chuyển thành Trường Trung học Độc lập Quốc gia với tên gọi Trường Trung học Malihud Quốc gia, và bố trí kinh phí","th":"พระราชบัญญัติแยกวิทยาเขต Malihud ของโรงเรียนมัธยมศึกษา Tarusan แห่งชาติในบารังไกย์ Malihud เทศบาล Bataraza จังหวัด Palawan ออกจากโรงเรียนมัธยมศึกษา Tarusan แห่งชาติและยกฐานะเป็นโรงเรียนมัธยมศึกษาเอกเทศแห่งชาติชื่อโรงเรียนมัธยมศึกษา Malihud แห่งชาติ และจัดสรรงบประมาณ","id":"Undang-Undang Memisahkan Kampus Malihud, Sekolah Menengah Tarusan Nasional di Barangay Malihud, Kotamadya Bataraza, Provinsi Palawan dari Sekolah Menengah Tarusan Nasional dan menjadi Sekolah Menengah Mandiri Nasional dengan nama Sekolah Menengah Malihud Nasional, dan mengalokasikan dana","ms":"Akta Memisahkan Kampus Malihud, Sekolah Menengah Tarusan Kebangsaan di Barangay Malihud, Perbandaran Bataraza, Wilayah Palawan daripada Sekolah Menengah Tarusan Kebangsaan dan menjadi Sekolah Menengah Bebas Kebangsaan dengan nama Sekolah Menengah Malihud Kebangsaan, dan memperuntukkan dana"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10810","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10810_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9258-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Tarusan National High School - Malihud Extension in Barangay Malihud, Municipality of Bataraza, Province of Palawan is hereby separated from the Tarusan National High School and converted into an independent national high school to be known as Malihud National High School."}},{"id":"PH-H9258-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, assets, liabilities and records of the Tarusan National High School - Malihud Extension are hereby transferred to and absorbed by the Malihud National High School."}},{"id":"PH-H9258-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department's program the operationlization of the Malihud National High School, the initial funding of which shall be charged against the current year's appropriation of the Tarusan National High School - Malihud Extension. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H9258-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education shall issue rules and regulations necessary to carry out the purpose of this Act."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Tarusan National High School - Malihud Extension in Barangay Malihud, Municipality of Bataraza, Province of Palawan From the Tarusan National High School, Converting It Into An Independent National High School to Be Known as Malihud National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
