  FT["PH-H9260"] = {"id":"PH-H9260","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10812_2016.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在三宝颜市San Roque描笼涯设立国立中学，名称为San Roque国立中学，并为此拨款的法案","en":"An Act Establishing a National High School in Barangay San Raque, Zamboanga City to Be Known as San Roque National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay San Raque, Zamboanga City to Be Known as San Roque National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay San Raque, Zamboanga City được biết đến với tên gọi Trường trung học phổ thông quốc gia San Roque","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ San Raque, Zamboanga City ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ San Roque","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay San Raque, Zamboanga City dikenal sebagai Sekolah Menengah Atas Nasional San Roque","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay San Raque, Zamboanga City dikenali sebagai Sekolah Menengah Kebangsaan San Roque"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10812","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-11","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10812_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9260-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established, under the suprevision of the Department of Education, a national high school in Barangay San Roque, Zamboanga City to be known as San Roque National High School."}},{"id":"PH-H9260-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education shall immediately include in the Department's program the operationalization of the San Roque National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9260-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall issue rules and regulations necessary to carry out the purpose of this Act."}},{"id":"PH-H9260-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a National High School in Barangay San Raque, Zamboanga City to Be Known as San Roque National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9261"] = {"id":"PH-H9261","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10813_2016.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Jabonga市","en":"An Act Establishing a Multi-Species Freshwater Hatchery in the Municipality of Jabonga, Province of Agusan Del Norte and Appropriating Funds Thererfor","orig":"An Act Establishing a Multi-Species Freshwater Hatchery in the Municipality of Jabonga, Province of Agusan Del Norte and Appropriating Funds Thererfor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10813","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-11","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10813_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9261-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Bureau of Fisheries and Aquatic Resources of the Department of Agriculture (BFAR-DA), a multi-species freshwater hatchery in the Municipality of Jabonga, Province of Agusan del Norte."}},{"id":"PH-H9261-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Within two (2) years after the construction of the multi-species freshwater hatchery, the BFAR shall, through a memorandum of agreement, transfer its management to the local government unit concerned. It shall implement a training and phasing-in program for local government personnel on the management and operation of the multi-species freshwater hatchery."}},{"id":"PH-H9261-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Agriculture shall include in the Department's program the establishment of the multi-species freshwater hatchery, the funding of which shall be included in the annual General Appropriations Act. The local government unit concerned shall set aside funds from any available local revenue in an amount deemed appropriate for the management and operation of the hatchery."}},{"id":"PH-H9261-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Agriculture shall issue the rules and regulations on the supervision and monitoring, and the transfer or withdrawal, by the BFAR of the multi-species freshwater hatchery."}},{"id":"PH-H9261-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132"};
  FT["PH-H9262"] = {"id":"PH-H9262","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10814_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"宣布每年6月23日为Bacoor市特别工作假日及学校停课日，以纪念其设市周年的法案","en":"An Act Declaring June 23 of Every Year as a Special Working Holiday and No Class Day in Schools in the City of Bacoor to Commemorate Its Anniversary as a City","orig":"An Act Declaring June 23 of Every Year as a Special Working Holiday and No Class Day in Schools in the City of Bacoor to Commemorate Its Anniversary as a City"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10814","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10814_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9262-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"June 23 of every year is hereby declared as a special working holiday and no class day in schools in the City of Bacoor to commemorate its anniversary as a City."}},{"id":"PH-H9262-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For work performed on a special working holiday, an employee is entitled to his/her regular wage."}},{"id":"PH-H9262-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring June 23 of Every Year as a Special Working Holiday and No Class Day in Schools in the City of Bacoor to Commemorate Its Anniversary as a City","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9263"] = {"id":"PH-H9263","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10815_2016.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"规定在西明多洛省 Rizal 市镇设立技术教育与技能发展中心，名称为 Rizal 技术教育培训与认证中心，并为此拨款的法案","en":"An Act Providing for the Establishment of a Technical Education and Skills Development Center in the Municipality of Rizal, Province of Occidental Mindoro to Be Known as the Rizal, Occidental Mindoro TESDA Training and Accreditation Center, and Appropriating Funds Therefor","orig":"An Act Providing for the Establishment of a Technical Education and Skills Development Center in the Municipality of Rizal, Province of Occidental Mindoro to Be Known as the Rizal, Occidental Mindoro TESDA Training and Accreditation Center, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10815","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-16","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10815_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9263-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the “Rizal, Occidental Mindoro TESDA Training and Accreditation Center Act”."}},{"id":"PH-H9263-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Establishment. – There is hereby established a Technical Education and Skills Development Center in the Municipality of Rizal, Province of Occidental Mindoro, under the supervision of the Technical Education and Skills Development Authority (TESDA), to be known as the Rizal, Occidental Mindoro TESDA Training and Accreditation Center."}},{"id":"PH-H9263-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"General Mandate. – The Rizal, Occidental Mindoro TESDA Training and Accreditation Center shall primarily provide technical-vocational training and skills development programs to students from low-income families and out-of-school youth in the Municipality of Rizal and adjacent municipalities in the Province of Occidental Mindoro. It shall also play a pivotal role in helping the students become productive, self-reliant and to develop into middle-level skilled labor force so as to hasten the social and economic development of Occidental Mindoro, as well as meet the needs of both local and international labor markets.\nThe Rizal, Occidental Mindoro TESDA Training and Accreditation Center shall also serve as the assessment center for acquired competencies in technical-vocational skills in the whole Province of Occidental Mindoro. Further, as deemed necessary and practicable, in coordination with the Department of Education (DepED), it shall render relevant teachers’ training assistance and curriculum design to the secondary schools offering technical-vocational education under the K to 12 Program of the DepED."}},{"id":"PH-H9263-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Curricular Offerings. – The Rizal, Occidental Mindoro TESDA Training and Accreditation Center shall offer short-term courses in preferred market-driven and relevant technical-vocational courses within its areas of specialization in consultation with the Department of Labor and Employment (DOLE) and such other relevant agencies, both local and international."}},{"id":"PH-H9263-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"School Site. – The Rizal, Occidental Mindoro TESDA Training and Accreditation Center shall be established on a site in the Municipality of Rizal, Province of Occidental Mindoro, which is highly accessible pursuant to the purposes of this Act and to the mutual agreement between the TESDA and the concerned local government unit (LGU)."}},{"id":"PH-H9263-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Administration. – The Rizal, Occidental Mindoro TESDA Training and Accreditation Center shall be headed by a Technical-Vocational Administrator under the supervision of the TESDA. The Technical-Vocational Administrator shall be appointed by the TESDA Director- General in accordance with civil service rules and regulations and the qualification requirements of the TESDA.\nThe Technical-Vocational Administrator shall render full-time services and shall be responsible for the administration and operation of the Rizal, Occidental Mindoro TESDA Training and Accreditation Center."}},{"id":"PH-H9263-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Appropriations. – The Director-General of the TESDA shall include in the Authority’s program the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9263-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Implementing Rules and Regulations. – Within sixty (60) days after the effectivity of this Act, the TESDA, in coordination with the DOLE, the Department of Trade and Industry (DTI), the concerned LGU, and such other relevant agencies, shall formulate and issue the necessary rules and regulations for the implementation of this Act."}},{"id":"PH-H9263-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Separability Clause. – If, for any reason, any section of this Act shall be deemed unconstitutional or invalid, the other sections or provisions hereof shall not be affected and shall thereby remain in force and effect."}},{"id":"PH-H9263-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Repealing Clause. – All laws, executive orders, decrees, instructions, rules and regulations contrary to or inconsistent with any provision of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H9263-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation"}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Technical Education and Skills Development Center in the Municipality of Rizal, Province of Occidental Mindoro to Be Known as the Rizal, Occidental Mindoro TESDA Training and Accreditation Center, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9264"] = {"id":"PH-H9264","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10816_2016.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"规定菲律宾农业旅游发展与推广的法案","en":"An Act Providing for the Development and Promotion of Farm Tourism in the Philippines","orig":"An Act Providing for the Development and Promotion of Farm Tourism in the Philippines"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 10816","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-16","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10816_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9264-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the “Farm Tourism Development Act of 2016”."}},{"id":"PH-H9264-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – The State recognizes the importance of agriculture in making available food and other products necessary to sustain and enhance human life, and in providing livelihood to a major portion of the population.\nThe State further recognizes that tourism, coupled with agriculture extension services, can disseminate the value of agriculture in the economic and cultural development of the country, serve as a catalyst for the development of agriculture and fishery communities, and provide additional income for farmers, farmworkers, and fisherfolk.\nThe State shall also seek to promote environment-friendly, efficient and sustainable farm practices; provide alternative recreation facilities and farm tourism activities for families, students and other clientele; and promote health and wellness with high-quality farm-produced food.\nTo maximize the benefits that can be derived from agriculture and tourism combined, it is therefore the declared policy of the State to provide the policy and enabling environment for the encouragement, development and promotion of farm tourism in the country."}},{"id":"PH-H9264-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. – As used in this Act, the following terms shall mean as follows:\n(a) Farm tourism – the practice of attracting visitors and tourists to farm areas for production, educational and recreational purposes. It involves any agricultural – or fishery – based operation or activity that brings to a farm visitors, tourists, farmers and fisherfolk who want to be educated and trained on farming and its related activities, and provides a venue for outdoor recreation and accessible family outings;\n(b) Farm tourism activity – any activity carried out on a farm that allows visitors and tourists to enjoy farming or fishing experience through education, recreation or leisure;\n(c) Farm tourism camp – any farm area that allows visitors and tourists to visit, get involved in farm activities, and to enjoy and learn rural lifestyle;\n(d) Farm tourism operator – any person, company or recognized group, who is the owner or overall in charge of a farm tourism camp;\n(e) Farm tourism practitioner – any person who is engaged in providing one or more farm tourism activities; and\n(f) Accreditation – a certification officially recognizing a farm tourism camp as having complied with the minimum standards for farm tourism."}},{"id":"PH-H9264-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Farm Tourism Strategic Action Plan. – There is hereby mandated the formulation and implementation of the Farm Tourism Strategic Action Plan, herein referred to as the Plan, which shall be the comprehensive set of programs, projects and activities for the growth of farm tourism in the country. The Plan shall be integrated and be made consistent with the National Tourism Development Plan.\nThe Plan shall cover, among others, the following areas of concern: investment promotion and financing; market research, trends, innovations, and information; accreditation of farm tourism camps; market promotion and development; agriculture and fishery research, development and extension; institutional and human resource development; and infrastructure support. It shall likewise define the roles and responsibilities of national government agencies, local government units (LGUs), farm tourism operators, tour operators, educational institutions, and other industry stakeholders in the implementation of the Plan."}},{"id":"PH-H9264-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Creation of the Farm Tourism Development Board. – To ensure the attainment of the objectives of this Act, there is hereby created the Farm Tourism Development Board, herein referred to as the Board, which shall be attached to the Department of Tourism (DOT). The Board shall formulate plans and programs for the development and promotion of farm tourism in the country and shall set the overall direction for the implementation of the Plan.\nThe Board shall have the following powers and functions:\n(a) Formulate, advocate, coordinate, oversee and assess the implementation of the Farm Tourism Strategic Action Plan;\n(b) Increase awareness on the value of farm tourism through advocacy campaigns and marketing activities;\n(c) Recommend infrastructure projects and transportation programs for funding by the DOT, the Department of Agriculture (DA), the Tourism Infrastructure and Enterprise Zone Authority (TIEZA), the Department of Public Works and Highways (DPWH), the Department of Transportation and Communications (DOTC), and other concerned government agencies;\n(d) Formulate and oversee the conduct of farm tourism research and development projects to ensure sustainability of the country’s farm tourism program, such as on market research, trends and innovations, and information dissemination; financing requirements; industry manpower development; resource productivity and utilization improvement; and sustainable agriculture practices and education;\n(e) Create technical panels, working groups, or task forces that will assist the Board in the performance of its functions;\n(f) Establish cooperation among, and/or request the assistance of, departments, bureaus, offices, agencies or instrumentalities of the government, farm tourism stakeholders, financial and educational institutions, nongovernment organizations, people’s organizations and other like-minded institutions and individuals in the implementation of its functions and the attainment of the objectives of this Act; and\n(g) Perform such other powers and functions which shall advance the development and promotion of farm tourism camps and activities."}},{"id":"PH-H9264-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Composition. – The Farm Tourism Development Board shall be composed of the following:\n(a) Secretary of the DOT as Chairperson;\n(b) Secretary of the DA as Vice-Chairperson;\n(c) Secretary of the Department of Trade and Industry (DTI);\n(d) The president of an educational institution providing farm tourism programs, to be identified by the DOT and the DA;\n(e) The president of a national farm tourism organization;\n(f) The president of a national inbound tour operators association; and\n(g) The president of a national federation of farmers cooperatives.\nThe DOT Secretary may designate the Undersecretary for Tourism Development as his/her alternate, and the DA and the DTI Secretaries may designate their respective alternates who shall be at least Bureau Director in rank, and their acts shall be considered the acts of their principals."}},{"id":"PH-H9264-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Board Secretariat. – There shall be a Board Secretariat to be composed of the DOT Office of Tourism Development Planning, Research and Information Management, and other technical personnel of the DOT, the DA and the DTI as assigned by their respective Secretaries. The Director of the Office of Tourism Development Planning, Research and Information Management shall head the Board Secretariat."}},{"id":"PH-H9264-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Investment Promotion, Financing and Incentives. – The DOT, the DA and the DTI shall develop programs linking stakeholders in the farm tourism industry, government financial institutions (GFIs), government-owned or -controlled corporations (GOCCs), private banks, financial cooperatives and other lending institutions to increase access to credit for farm tourism. The Land Bank of the Philippines, the Development Bank of the Philippines, the Small Business Corporation, and other government corporations and instrumentalities providing financing programs shall create lending windows to cater to the development of farm tourism camps and activities.\nThe TIEZA and the Board of Investments, and other investment promotion agencies, shall develop and implement programs that shall establish reasonable and innovative investment incentives to attract more investors and farm tourism practitioners in the farm tourism industry.\nFarm tourism operators and practitioners may avail o: incentives under existing laws."}},{"id":"PH-H9264-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Market Research and Information. – The DOT Office of Tourism Development Planning, Research and Information Management and the Agricultural Training Institute (ATI) o: the DA shall conduct researches and studies on farm tourisim market, trends and innovations, industry manpower needs and development; sustainable agriculture practices and education, and other issues that may be identified by the Board.\nThe DOT and the DA shall collaborate and maintain a comprehensive farm tourism information system to assist the government in formulating plans and programs on farm tourism development and to enable industry stakeholders respond to the needs of the market. The information system shall contain information and statistics on farm tourism camps and activities, market researches, accessibility and available modes of transportation, publications and research materials, and other information as identified by the Board."}},{"id":"PH-H9264-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Accreditation of Farm Tourism Camps. – The DOT and the DA shall jointly promulgate and enforce the standards and guidelines on the accreditation of farm tourism camps.\nAccreditation shall be on a voluntary basis and shall be valid for two (2) years.\nAccreditation may be suspended or revoked for any violation of the standards."}},{"id":"PH-H9264-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Market Promotion and Development. – The DOT and the Tourism Promotions Board, the DA, the DTI and LGUs shall include farm tourism in their marketing and promotions programs, and support operators of accredited farm tourism camps and their associations in conducting and joining local and international conferences, congresses, trade fairs, and exhibits.\nInbound tour operators shall include accredited farm tourism camps as part of their suggested itineraries.\nThe ATI and the Technical Education and Skills Development Authority (TESDA) shall showcase farm tourism camps and activities as a way of promoting sustainable agriculture. The ATI shall encourage farm tourism camps to become learning sites and accredited extension service providers, and the TESDA shall accredit farm tourism camps as technical vocational institutions for agriculture and tourism courses.\nThe DTI Bureau of Small and Medium Enterprise Development and the Bureau of Domestic Trade Promotion and the DA – Agribusiness and Marketing Assistance Service shall assist farm tourism operators and practitioners in the marketing and distribution of their products, and link them with consumers cooperatives and organizations, and retailers.\nThe DOT, the DA, and the Philippine Information Agency (PIA) shall launch and pursue a nationwide campaign to promote farm tourism and accredited farm tourism camps, and promote the principle of sustainable development. For this purpose, the DOT and the DA shall encourage the establishment of at leas’ one (1) farm tourism camp in every province in the country."}},{"id":"PH-H9264-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Agriculture and Fishery Research, Development and Extension. – The Philippine Council for Agriculture, Aquatic and Natural Resources Research and Development and the Bureau of Agricultural Research shall include the technology needs on farm tourism camps in the research and development programs in agriculture, aquatic and natural resources and shall disseminate such results to the DOT, the DA, the DTI, other concerned government agencies, farm tourism operators and practitioners, state universities and colleges (SUCs) and private educational institutions offering educational programs on farm tourism development, and organizations engaged in farm tourism The ATI, together with the Cooperative Development Authority (CDA), SUCs, educational and research institutions and other relevant government agencies shall develop and implement programs for the adoption of technologies appropriate for farm tourism, provide adequate training and agricultural extension services for farm tourism practitioners and operators and strengthen farm tourism cooperatives and organizations."}},{"id":"PH-H9264-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Institutional and Human Resource Development. – The DOT, the DA, the DTI, the Department of Science and Technology (DOST), the Commission on Higher Education (CHED), the TESDA, SUCs, private educational and research institutions, and other private sector groups shall establish ant implement an institutional and human resource development program for farm tourism development, which shall include, but not be limited to:\n(a) Capacity building for farm tourism operators to enable them to comply with the DOT, the ATI and the TESDA accreditations standards as primary or secondary tourism enterprises, as extension service providers, and as technical vocational institutions, respectively;\n(b) Technical-vocational education and training for farm tourism industry practitioners, including farm tourism camp workers, to actively contribute to productivity, the practice of good agricultural, animal husbandry and manufacturing practices, compliance to food safety, health, hygiene and sanitation standards, and adherence to hospitality management practices;\n(c) Formulation and implementation of competency standards and training regulations for technical-vocational education and training for the farm tourism industry; and\n(d) Capability building for LGUs in the promotion, development and sustainability of farm tourism camps and activities."}},{"id":"PH-H9264-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Infrastructure Support. – The DPWH, the DOTC, the DA, and other infrastructure agencies shall include in their annual development plans and priority investment programs infrastructure projects and transportation programs to expand access to farm tourism camps. The DOT and the DA shall coordinate with these agencies the infrastructure requirements of established and potential farm tourism camps."}},{"id":"PH-H9264-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Implementing Rules and Regulations. – The Board, in consultation with concerned government agencies, LGUs and their leagues, and farm tourism industry stakeholders, shall issue the implementing rules and regulations within ninety (90) days starting from the effectivity of this Act."}},{"id":"PH-H9264-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders, rules and regulations and other issuances or parts thereof, inconsistent with the provisions of this Act, are hereby repealed or modified accordingly."}},{"id":"PH-H9264-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause. – If any part or provision of this Act is declared unconstitutional or invalid, other parts or provisions herein which are not affected thereby shall continue i be in full force and effect."}},{"id":"PH-H9264-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a nation newspaper of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Development and Promotion of Farm Tourism in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9265"] = {"id":"PH-H9265","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10817_2016.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":"制定菲律宾清真出口开发与促进计划、为此设立菲律宾清真出口开发与促进委员会并为其他目的法案","en":"An Act Instituting the Philippine Halal Export Development and Promotion Program, Creating for the Purpose the Philippine Halal Export Development and Promotion Board, and for Other Purposes","orig":"An Act Instituting the Philippine Halal Export Development and Promotion Program, Creating for the Purpose the Philippine Halal Export Development and Promotion Board, and for Other Purposes"},"level":"law","status":"active","topics":["trade"],"docNumber":"Republic Act No. 10817","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-16","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10817_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9265-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the “Philippine Halal Export Development and Promotion Act of 2016”."}},{"id":"PH-H9265-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – Recognizing the significant role of exports to national economic development, and the potential contribution of Halal industries, it is hereby declared the policy of the State to promote the growth and ensure the integrity and quality of Philippine Halal exports.\nWith the internationalization of markets brought about by globalization and economic integration, and mindful of the State’s commitment under international trade agreements including multilateral and bilateral mutual recognition agreements, harmonization of standards to international standards and compliance to standards of Halal products, processes and services become indispensable. The State, therefore, shall assert its right to exercise police power against trade malpractices.\nIt is also the policy of the State to develop and promote Halal industries as a mode of achieving equity and justice among our farmers and producers, and increasing employment opportunities for the domestic labor force. With this, the State shall adopt measures to make Halal exports more competitive through, among others, research and product development, quality assurance measures, value-adding mechanisms, thereby making the Philippines an active player in regional and international markets and not just a mere spectator of globalized trade.\nLastly, it shall also be the policy of the State to protect consumers and users of Halal products, processes and services from unscrupulous and unfair agricultural, manufacturing and trade practices.\nTowards these ends, the State shall establish a comprehensive program for the development and promotion of Halal export, provide the policy, regulatory, and coordinative structures and mechanisms for the promotion and export of Philippine Halal products, and institute measures and provide programs to ensure compliance and integrity of producers, manufacturers and providers of Halal products, processes and services to national and/or international or foreign standards."}},{"id":"PH-H9265-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. – As used in this Act, the following terms shall have the following definition:\n(a) Accreditation refers to the procedure by which a government agency having jurisdiction formally attests to the competence of an inspection and/or certification body to provide inspection and certification services;\n(b) Certification refers to third party attestation of conformance to standards and guidelines related to products, processes, systems or persons;\n(c) Halal refers to lawful or permissible under Sharia’h (Islamic Law);\n(d) Processes refer to a set of interrelated or interacting activities which transforms inputs to outputs;\n(e) Products refer to food and nonfood items produced by human or mechanical effort, or by a natural process, or a combination thereof, and marketed or sold as a commodity;\n(f) Recognition refers to the acknowledgment of the validity of a conformity assessment result provided by a person or body; and\n(g) Services refer to an intangible result of at least one (1) activity performed by a supplier or provider for a customer."}},{"id":"PH-H9265-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Philippine Halal Export Development and Promotion Program. – There is hereby established the Philippine Halal Export Development and Promotion Program, which shall refer to the comprehensive set of objectives, targets, strategies and activities for the growth of Halal industries producing or providing products, processes and services and resulting to increased exports of Halal products.\nIt shall include, but not be limited to, the following areas of concern: the development and application of Halal agricultural and manufacturing standards and practices; the organization and development of accredited certification bodies through, among others, capacity building and the formulation and application of internationally-accepted accreditation standards; identification and expansion of markets for Halal products, processes and services; forging of international and bilateral agreements especially on harmonization of standards; compliance of producers, manufacturers, service providers, traders and exporters to established local or international standards; industry development and promotion, including expansion into nonfood Halal products and services; consumer awareness and fair trade practices; and provision of common service facilities."}},{"id":"PH-H9265-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Creation of Philippine Halal Export Development and Promotion Board. – To ensure the attainment of the objectives of this Act, there is hereby created the Philippine Halal Export Development and Promotion Board, herein referred to as the Halal Board. The Halal Board shall be the policy-making body on Halal export development and shall set the overall direction for the implementation of the Philippine Halal Export Development and Promotion Program. It shall be attached to the Department of Trade and Industry.\nIn the performance of its mandate, the Halal Board shall institutionalize the involvement of Muslim Filipino people’s organizations and nongovernment organizations through membership in consultative or advisory bodies, coordination of activities with government agencies concerned with Halal industry development, and participation in regular consultative mechanisms such as public hearings and roundtable discussions."}},{"id":"PH-H9265-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Powers and Functions. – The Halal Board shall have the following powers and functions:\n(a) Formulate, advocate, coordinate, oversee and assess the implementation of the Philippine Halal Export Development and Promotion Program;\n(b) Direct and coordinate the development and harmonization of Philippine National Standards for Halal by standard setting agencies, and monitor, through the government regulatory agencies, the application thereof on products, processes and services;\n(c) Spearhead and support the forging of international agreements, and the recognition of accredited Halal certification bodies in other countries, to open new and expand existing markets for Halal products, processes and services;\n(d) Issue the Philippine Halal Logo and the guidelines on the proper use thereof: Provided, That the use of logos of certification bodies on certified products, processes and services shall be without prejudice: Provided, further, That all other government agencies are prohibited to issue a logo and require the use of such logo as proof of compliance to a standard or regulation as Halal: Provided, finally, That the use of logos previously issued by government agencies involved in Halal development and promotion is hereby disallowed;\n(e) Encourage and support the establishment of a single umbrella organization of Halal certification bodies, which can be tapped by standard setting and regulatory agencies to assist in the development and in monitoring the application of internationally-accepted Halal certification standards;\n(f) Promulgate policies and guidelines as necessary or proper for the accomplishment of the objectives of this Act, including the Halal Board’s operation;\n(g) Create technical panels, working groups, or task forces that will assist the Halal Board in the performance of its functions;\n(h) Investigate and make recommendations on complaints, controversies, or disputes arising out of the implementation or enforcement of standards, guidelines, rules and procedures adopted to promote and develop Halal industries, the export of Halal products and the provision of Halal processes and services;\n(i) Request the assistance and cooperation of any department, bureau, office, agency or instrumentality of the government, or private entities and organizations in the implementation of its functions and the attainment of the objectives of this Act, including the carrying out of recommendations as a result of investigations and studies made pursuant to paragraphs (g) and (h) hereof; and\n(j) Perform such other powers and functions as may be prescribed by law, or may be necessary, incidental, or proper to its mandate."}},{"id":"PH-H9265-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Composition of the Halal Board. – The Halal Board shall be composed of:\n(a) The Secretary of the Department of Trade and Industry (DTI) as Chairperson;\n(b) The Secretary of the National Commission on Muslim Filipinos (NCMF) as Vice Chairperson;\n(c) The Secretary of the Department of Agriculture (DA);\n(d) The Secretary of the Department of Health (DOH);\n(e) The Secretary of the Department of Science and Technology (DOST);\n(f) The Secretary of the Department of Foreign Affairs (DFA);\n(g) The Secretary of the Department of Tourism (DOT);\n(h) The Governor of the Bangko Sentral ng Pilipinas (BSP);\n(i) The Chairperson of the Mindanao Development Authority (MinDA); and\n(j) Two (2) Muslim Filipino professionals from the academe, law, industry, or food science who have experience in Halal industry development, to be appointed by the President from at least four (4) nominees recommended by Muslim Filipino people’s organizations and nongovernment organizations.\nThe two (2) Muslim professionals shall serve for a term of three (3) years, and may be reappointed once.\nThe ex officio members of the Halal Board may designate their respective alternates who shall be at least Bureau Director in rank and their acts shall be considered the acts of their principals."}},{"id":"PH-H9265-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Secretariat of the Halal Board. – The DTI Secretary, as Chairperson of the Halal Board, shall establish an interagency secretariat from the different bureaus of the DTI concerned with Halal export development, the NCMF, the DA and the DOH. The Secretariat shall be headed by the Director of the Export Marketing Bureau. For this purpose, the Export Marketing Bureau shall be strengthened and is hereby authorized to create a section that will serve as the nucleus of the Secretariat of the Halal Board.\nThe Secretaries of the NCMF, the DA and the DOH shall assign technical staff of their offices as staff of the Secretariat. Other member agencies shall provide additional staff support upon the determination of the necessity by the Chairperson and conformity of the Halal Board."}},{"id":"PH-H9265-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Accreditation of Halal Certification Bodies. – As the agency mandated to handle the accreditation of certification bodies, inspection bodies, and testing and calibration laboratories, the Philippine Accreditation Bureau (PAB) is hereby empowered to: (a) formulate accreditation policies and guidelines which shall govern the accreditation of Halal certification bodies; and (b) grant or deny accreditation of Halal certification bodies and suspend or withdraw such accreditation in accordance with established policies and guidelines.\nIn the formulation of accreditation policies and guidelines, and in the performance of its accreditation function, the PAB shall consult and, when necessary, collaborate with the Halal Board, its member agencies, and Halal industry stakeholders."}},{"id":"PH-H9265-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Philippine National Standards for Halal. – The development of Philippine National Standards for Halal shall be the mandate of the following standard setting agencies:\n(a) Department of Agriculture – Bureau of Agriculture and Fisheries Standards (BAFS) – for primary and post-harvest foods;\n(b) Department of Health – Food and Drug Administration (FDA) – for processed and prepackaged foods, drugs and cosmetics; and\n(c) Department of Trade and Industry – Bureau of Philippine Standards (BPS) – for nonfood products aside from drugs and cosmetics.\nOther products, processes and services that would necessitate the development of the corresponding Philippine National Standards for Halal which are not covered by the above agencies shall be assigned by the Halal Board to appropriate government agencies."}},{"id":"PH-H9265-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Export and Trade Regulation of Halal Products, Processes and Services. – The following conditions shall apply in the export and trade of Halal products, processes and services:\n(a) All Philippine products that will be exported as Halal, and processes and services whose outputs or benefits shall accrue or flow outside of the Philippine territory, shall (i) undergo certification from an accredited Halal certification body, (ii) comply with the appropriate Philippine National Standards for Halal as developed, or with international or foreign standards recognized, by standard setting agencies identified or mandated under Section 10 of this Act, and (iii) be registered with the national regulatory agency concerned;\n(b) The Philippine Halal Logo, with the permission of the relevant regulatory agency, shall be affixed or used by producers, manufacturers, processors, traders, exporters, and service providers on their products, packaging, letterheads, brochures, leaflets and other forms of media after complying with the conditions set in paragraph (a) hereof;\n(c) Halal certification of products, processes and services for domestic consumption or use is voluntary on the part of the producer, manufacturer, trader, retailer, or service provider; and\n(d) Producers, manufacturers, traders, retailers, and service providers catering the domestic market and have undergone voluntary certification from accredited Halal certification bodies may apply and be granted permission to use the Philippine Halal Logo on their products, establishments, or facilities."}},{"id":"PH-H9265-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Export Promotion. – The DTI, particularly the Export Marketing Bureau, in coordination with the DA, the DOH, and other concerned government agencies, shall enhance the capabilities and global competitiveness of existing and potential exporters of Halal products, processes and services, through business matching; provision of trade and market information; organization of trade fairs and business missions; conduct of seminars, workshops, conferences and symposium on export-related subjects, including export documentation and procedures; product design and development; market consultancy; and product consultancy.\nTo assist exporters find new and expand existing markets for Philippine Halal products, processes and services, the DTI and the DA shall task their Foreign Trade Service Corps and Foreign Agriculture Service Corps, respectively, to conduct commercial intelligence works and marketing activities. In addition, the DTI, together with the NCMF and the DFA shall pursue the recognition of accredited Halal certification bodies and certified Halal products, processes and services by accreditation and certification bodies of other countries."}},{"id":"PH-H9265-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Infrastructure Support and Incentives. – To enhance the growth of Halal industries and assist farmers and producers in complying with the relevant Halal standards, the government, especially the DA, shall provide and/or upgrade necessary common service facilities such as slaughterhouses, warehouses, refrigeration facilities, and laboratory facilities and equipment, in strategic production, processing and manufacturing areas.\nThe Board of Investments, the Philippine Economic Zone Authority, and other investment promotion agencies are hereby mandated to promote the growth of Halal industries in the different economic zones and strategic locations in the country. They shall, as their charters allow, grant fiscal and non-fiscal incentives to attract investments in pioneering and essential industries to increase exports of Halal products or as raw materials or ingredients in the production of Halal products."}},{"id":"PH-H9265-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Institutional and Human Resource Development. – The DTI, the NCMF, the DA, the DOH, the DOST, the Commission on Higher Education (CHED), the Technical Education and Skills Development Authority (TESDA), state universities and colleges (SUCs), certification bodies, the private sector, and Muslim Filipino organizations shall establish and implement an institutional and human resource development program for Halal industry development which shall include, but not limited to:\n(a) Capacity building for producers, manufacturers and processors to enable them to comply with certification standards, including knowledge on facilities upgrading and retrofitting, adoption of accepted manufacturing practices, product and packaging development, marketing and product distribution, and business enterprise development;\n(b) Skills trainings for Halal industry workers, farmers, fishermen, and producers to actively contribute in productivity, the practice of good agricultural, animal husbandry and manufacturing practices, and compliance to food safety, health, hygiene and sanitation standards;\n(c) Scholarship program for the underprivileged but deserving college and post graduate students who are taking up courses in relevant field of disciplines in SUCs which have programs in agriculture and fisheries; and for technical- vocational courses for farmers, fishermen, farm technicians, and skilled workers in processing and manufacturing plants producing or providing Halal products, processes and services;\n(d) Formulation and implementation of competency standards and training regulations for technical-vocational education and training for the Halal industry by the TESDA; and\n(e) Upgrading of facilities, faculty development and strengthening of the on-the-job training program of higher education institutions in Halal technology and standards towards the build-up of competent graduates needed by Halal industries."}},{"id":"PH-H9265-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Research, Development and Extension (RDE). – The DTI, the DA, the DOH, the DOST, the CHED, SUCs and private organizations shall formulate and implement a national research, development and extension program to develop, propagate, or commercialize products and technologies and to improve and expand the number of Halal products, processes and services.\nSUCs with the capability to support RDE for Halal shall be identified and assisted by the CHED, in coordination with the DOST, the DA, the DTI and the DOH, the private sector, and Muslim Filipino organizations to become centers of development and excellence in Halal.\nThe DOST shall upgrade the capability of the PAB, the BPS, the FDA, the BAFS, other regulatory agencies, Halal certification bodies, producers, manufacturers and service providers in ensuring integrity and compliance to standards by imparting scientific and technical knowledge on Halal standards and in conducting laboratory analyses through its Philippine National Halal Laboratory and Science Center."}},{"id":"PH-H9265-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Applicability of Fair Trade, Consumer Protection and Copyright Laws and Regulatory Agency Charters. – The relevant provisions of fair trade, consumer protection and copyright laws, and their implementing rules or orders, as well as the charters of regulatory and standard setting agencies shall be applied in the implementation of this Act to ensure compliance with Philippine National Standards on Halal and the use of the Philippine Halal Logo. Nothing herein shall be construed as limiting any department, agency or bureau from imposing, applying or enforcing the necessary fines and penalties under these laws.\nThe appropriate agencies of the DTI, the NCMF, the DA, and the DOH shall conduct consumer protection and advocacy programs to create awareness among consumers on Halal products, processes and services, and enable them to determine and complain unfair trade practices."}},{"id":"PH-H9265-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Authority to Receive Donations and/or Grants. – The Halal Board is hereby authorized to accept grants, contributions, endowments, bequests, from local and foreign sources in support of the development and growth of Philippine Halal industries, including the development of Philippine National Standards for Halal, institutional development of certification bodies, producers, manufacturers and service providers, and consumer advocacy campaigns: Provided, That such donations shall not be used to fund personal services and other operating expenses of the Halal Board."}},{"id":"PH-H9265-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Appropriations. – The amount necessary for the initial implementation of this Act shall be charged against the current appropriations of the DTI. Thereafter, such amount as may be necessary for the continuous operation of the Halal Board and the implementation of the Program shall be included in the annual General Appropriations Act."}},{"id":"PH-H9265-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Transitory Provisions. – The Philippine Halal Promotion, Development and Accreditation Board, under the NCMF, is hereby dissolved. All Halal promotion and development records of the Board shall be transferred to the Halal Board, while accreditation records shall be transferred to the PAB."}},{"id":"PH-H9265-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Implementing Rules and Regulations. – The Halal Board, in consultation with concerned government agencies, Muslim Filipino organizations, and Halal industry stakeholders, shall issue the implementing rules and regulations of this Act within ninety (90) days starting from the effectivity of this Act."}},{"id":"PH-H9265-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders and rules and regulations or part or parts thereof inconsistent with any provision of this Act are hereby repealed, modified or amended accordingly."}},{"id":"PH-H9265-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Separability Clause. – If any provision of this Act is declared unconstitutional, the validity of the remaining provisions hereof shall remain in full force and effect."}},{"id":"PH-H9265-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Instituting the Philippine Halal Export Development and Promotion Program, Creating for the Purpose the Philippine Halal Export Development and Promotion Board, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9266"] = {"id":"PH-H9266","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10818_2016.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"将授予 Radio Mindanao Network，Inc. 的特许经营权再续展二十五年，自 2016 年 4 月 18 日起生效的法案","en":"An Act Renewing the Franchise Granted to the Radio Mindanao Network, Inc. for Another Twenty-Five (25) Years or a Term That Shall Take Effect on April 18, 2016","orig":"An Act Renewing the Franchise Granted to the Radio Mindanao Network, Inc. for Another Twenty-Five (25) Years or a Term That Shall Take Effect on April 18, 2016","vi":"Đạo luật gia hạn thêm 25 năm đặc quyền đã cấp cho Radio Mindanao Network, Inc.","th":"พระราชบัญญัติต่ออายุสัมปทานที่ให้แก่ Radio Mindanao Network, Inc. อีก 25 ปี","id":"Undang-Undang memperpanjang selama 25 tahun lagi konsesi yang diberikan kepada Radio Mindanao Network, Inc.","ms":"Akta melanjutkan selama 25 tahun lagi konsesi yang diberikan kepada Radio Mindanao Network, Inc."},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 10818","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-16","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10818_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9266-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and, Scope of Franchise. – Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, the franchise granted to the Radio Mindanao Network, Inc., under Republic Act No. 3122, entitled “An Act Granting the Radio Mindanao Network, Inc., of the Philippines a Franchise to Construct, Operate and Maintain Commercial Television and Radio Broadcasting Stations Within the Philippines”, as amended by Republic Act No. 6980, hereunder referred to as the grantee, its successors or assigns, to construct, install, establish, operate and maintain for commercial purposes and in the public interest, radio and/or television broadcasting stations, including digital television system, through microwave, satellite or whatever means, including the use of any new technologies in television and radio systems, with the corresponding technological auxiliaries and facilities, special broadcast and other program and distribution services and relay stations in the Philippines, is hereby renewed for another twenty-five (25) years from the approval of this Act."}},{"id":"PH-H9266-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may he established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee’s services and/or availability thereof."}},{"id":"PH-H9266-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission (NTC) the appropriate permits and licenses for the construction and operation of its stations and facilities and shall not use any frequency in the radio/television spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H9266-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations and facilities for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, to the detriment of the public interest, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H9266-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order: to temporarily take over and operate the stations or facilities of the grantee; to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when these shall be so operated.\nThe radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn any time after due process."}},{"id":"PH-H9266-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be in effect for a period of twenty-five (25) years from April 18, 2016, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H9266-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this new franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H9266-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Self-regulation by and Undertaking of Grantee. – The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations: Provided, That the grantee, during any broadcast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H9266-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H9266-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any lease, transfer, granting the usufruct of, sale or assignment of franchise or the rights and privileges acquired thereunder, or of the merger, or transfer of controlling interest of the grantee, within sixty (60) days after the completion of said transaction: Provided, further, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred or assigned shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H9266-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty per centum (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations: Provided, That in cases where public offer of shares is not applicable, establishment of cooperatives and other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9266-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law, which Congress may hereafter enact."}},{"id":"PH-H9266-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the term of the franchise."}},{"id":"PH-H9266-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Penalty Clause. – Failure to submit the annual report to Congress will be penalized with a fine of five hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from the delinquent franchise grantee separate from the reportorial penalties imposed by the NTC. The collected funds shall accrue to the monitoring fund of the NTC in line with its supervisory and regulatory functions. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9266-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Equality Clause. – Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or which may hereafter be granted for radio and/or television broadcasting, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, however, That the foregoing shall neither apply to nor affect provisions of broadcasting franchises concerning territory covered by the franchise, the life span of the franchise, or the type of service authorized by the franchise: Provided, further, That the foregoing shall not apply to sale, lease, transfer, or grant of usufruct of legislative franchise with prior congressional approval."}},{"id":"PH-H9266-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9266-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repeatability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H9266-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days sifter its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing the Franchise Granted to the Radio Mindanao Network, Inc. for Another Twenty-Five (25) Years or a Term That Shall Take Effect on April 18, 2016","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9267"] = {"id":"PH-H9267","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10819_2016.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"将依第 8115 号共和国法授予 Far East 广播公司（菲律宾）在菲律宾建设、维护和运营非商业无线电广播站的特许经营权续展的法案","en":"An Act Renewing the Franchise Granted to Far East Broadcasting Company (Philippines), Inc. Under Republic Act No. 8115, Entitled “An Act Granting the Far East Broadcasting Company (Philippines), Inc., a Franchise to Construct, Maintain and Operate Non-Commercial Radio Broadcasting Stations in the Philippines”","orig":"An Act Renewing the Franchise Granted to Far East Broadcasting Company (Philippines), Inc. Under Republic Act No. 8115, Entitled “An Act Granting the Far East Broadcasting Company (Philippines), Inc., a Franchise to Construct, Maintain and Operate Non-Commercial Radio Broadcasting Stations in the Philippines”","vi":"Đạo luật gia hạn đặc quyền đã cấp cho Far East Broadcasting Company theo Đạo luật Cộng hòa số 8115","th":"พระราชบัญญัติต่ออายุสัมปทานที่ให้แก่ Far East Broadcasting Company ตามพระราชบัญญัติแห่งสาธารณรัฐหมายเลข 8115","id":"Undang-Undang memperpanjang konsesi yang diberikan kepada Far East Broadcasting Company berdasarkan Undang-Undang Republik Nomor 8115","ms":"Akta melanjutkan konsesi yang diberikan kepada Far East Broadcasting Company di bawah Akta Republik No. 8115"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 10819","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-18","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10819_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9267-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and, Scope of Franchise. – Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, the franchise granted to the Far East Broadcasting Company (Philippines), Inc., under Republic Act No. 8115, entitled “An Act Granting the Far East Broadcasting Company (Philippines), Inc., a Franchise to Construct, Maintain and Operate Non-commercial Radio Broadcasting Stations in the Philippines”, hereunder referred to as the grantee, its successors or assignees, to construct, install, establish, operate and maintain for non-commercial purposes and in the public interest, radio and/or television broadcasting stations in the Philippines, is hereby renewed for another twenty-five (25) years from the effectivity of this Act."}},{"id":"PH-H9267-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee’s services and/or the availability thereof."}},{"id":"PH-H9267-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission (NTC) the appropriate permits and licenses for the construction and operation of its stations and facilities and shall not use any frequency in the radio spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H9267-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations and facilities for the broadcasting of obscene and indecent language, speech, act or scene; or for the dissemination of deliberately false information or willful misrepresentation, to the detriment of the public interest, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H9267-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order: to temporarily take over and operate tbe stations or facilities of the grantee; to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of the stations or facilities during the period when these shall be so operated.\nThe radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn anytime after due process."}},{"id":"PH-H9267-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be in effect for a period of twenty-five (25) years from the effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H9267-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and, Compliance. – Acceptance of this new franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H9267-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Self-regulation by and Undertaking of Grantee. – The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations: Provided, That the grantee, during any broadcast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H9267-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H9267-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation, or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any lease, transfer, grant of usufruct, sale, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger or sale of the controlling interest, within sixty (60) days after the completion of said transaction: Provided, further, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H9267-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Dispersed of Ownership. – In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations: Provided, That in cases where public offer of shares is not applicable, establishment of cooperatives and other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9267-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H9267-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the term of its franchise. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9267-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Penalty Clause. – Failure to submit the annual report to Congress shall be penalized with a fine of five hundred pesos (P500.00) per working day of noncompliance. The fine will be collected by the NTC from said delinquent franchise grantee separate from the reportorial penalties imposed by the NTC. The collected funds shall accrue to the monitoring fund of the NTC in line with its supervisory and regulatory functions."}},{"id":"PH-H9267-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Equity Clause. – Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or which may hereafter be granted for radio and/or television broadcasting, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, That the foregoing shall neither apply to nor affect provisions of broadcasting franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise: Provided, further, That the foregoing shall not apply to the sale, lease, transfer, grant of usufruct, or assignment of legislative franchises with prior congressional approval."}},{"id":"PH-H9267-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9267-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repeatability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H9267-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing the Franchise Granted to Far East Broadcasting Company (Philippines), Inc. Under Republic Act No. 8115, Entitled “An Act Granting the Far East Broadcasting Company (Philippines), Inc., a Franchise to Construct, Maintain and Operate Non-Commercial Radio Broadcasting Stations in the Philippines”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9268"] = {"id":"PH-H9268","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10820_2016.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"将依第 7163 号共和国法（经第 8162 号共和国法修正）授予 Progressive 广播公司的特许经营权再续展二十五年的法案","en":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Progressive Broadcasting Corporation Under Republic Act No. 7163, as Amended By Republic Act No. 8162","orig":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Progressive Broadcasting Corporation Under Republic Act No. 7163, as Amended By Republic Act No. 8162","vi":"Đạo luật gia hạn thêm 25 năm quyền khai thác đã cấp cho Progressive Broadcasting Corporation","th":"พระราชบัญญัติต่ออายุสัมปทานที่ให้แก่ Progressive Broadcasting Corporation อีก 25 ปี","id":"Undang-Undang memperpanjang waralaba yang diberikan kepada Progressive Broadcasting Corporation selama 25 tahun lagi","ms":"Akta memperbaharui francais yang diberikan kepada Progressive Broadcasting Corporation selama 25 tahun lagi"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 10820","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-18","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10820_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9268-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, the franchise granted to Progressive Broadcasting Corporation, hereunder referred to as the grantee, its successors or assignees, under Republic Act No. 7163, as amended by Republic Act No. 8162 entitled: “An Act Amending Section One of Republic Act Numbered Seventy-One Hundred Sixty Three, entitled: ‘An Act Granting Progressive Broadcasting Corporation a Franchise to Construct, Install, Operate and Maintain, for Commercial Purposes, Radio Broadcasting Stations and Television Stations in Metro Manila and in Regions I, VI and VII, and for Other Purposes,’ for the Purpose of Extending its Operations Throughout the Philippines”, to construct, install, establish, operate and maintain for commercial purposes and in the public interest, radio and/ or television broadcasting stations, including digital television system, through microwave, satellite or whatever means, including the use of new technologies in television and radio systems, with the corresponding technological auxiliaries and facilities, special broadcast and other program, and distribution services and relay stations in the Philippines, is hereby renewed for another twenty-five (25) years from the effectivity of this Act."}},{"id":"PH-H9268-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee’s services and/or the availability thereof."}},{"id":"PH-H9268-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission (NTC). – The grantee shall secure from the NTC the appropriate permits and licenses for the construction and operation of its stations and facilities and shall not use any frequency in the radio/television spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of such authority."}},{"id":"PH-H9268-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide adequate public service time to enable the government, through its broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations and facilities for the broadcasting of obscene and indecent language, speech, act or scene; or for the dissemination of deliberately false information or willful misrepresentation, to the detriment of the public interest; or to incite, encourage ox assist in subversive or treasonable acts."}},{"id":"PH-H9268-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order: to temporarily take over and operate the stations or facilities of the grantee; to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when these shall be so operated.\nThe radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn any time after due process."}},{"id":"PH-H9268-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be in effect for a period of twenty-five (25) years from the effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H9268-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this new franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H9268-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Self-regulation by and Undertaking of the Grantee. – The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations: Provided, That the grantee, during any broadcast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion, or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H9268-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H9268-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any lease, transfer, grant of usufruct, sale, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger or transfer of the controlling interest of the grantee, within sixty (60) days after the completion of the transaction: Provided, further, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred, or assigned, shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H9268-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations: Provided, That in cases where public offer of shares is not applicable, establishment of cooperatives and other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9268-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H9268-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the term of its franchise. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9268-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Penalty Clause. – Failure of the grantee to submit the requisite annual report to Congress shall be penalized with a fine of five hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from the delinquent franchise grantee, separate from tab reportorial penalties imposed by the NTC."}},{"id":"PH-H9268-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Equality Clause. – Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or which may hereafter be granted for radio andI or television broadcasting, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, That the foregoing shall neither apply to nor affect provisions of broadcasting franchises concerning territory covered by the franchise, the life span of the franchise, or the type of service authorized by the franchise."}},{"id":"PH-H9268-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9268-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repeatability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H9268-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Progressive Broadcasting Corporation Under Republic Act No. 7163, as Amended By Republic Act No. 8162","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9269"] = {"id":"PH-H9269","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10821_2016.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"规定在灾害及其他紧急情况发生前、中、后为儿童提供紧急救济与保护的法案","en":"An Act Mandating the Provision of Emergency Relief and Protection for Children Before, During, and After Disasters and Other Emergency Situations","orig":"An Act Mandating the Provision of Emergency Relief and Protection for Children Before, During, and After Disasters and Other Emergency Situations"},"level":"law","status":"active","topics":["civil","defence"],"docNumber":"Republic Act No. 10821","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-18","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10821_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9269-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the “Children’s Emergency Relief and Protection Act”."}},{"id":"PH-H9269-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – It is hereby declared the policy of the State to protect the fundamental rights of children before, during, and after disasters and other emergency situations when children are gravely threatened or endangered by circumstances that affect their survival and normal development. Guided by the principles on survival and development, on child participation, and consistent with the United Nations Convention on the Rights of the Child, as well as the Children’s Charter for Disaster Risk and Reduction, and the minimum standards for children in humanitarian action, the State shall establish and implement a comprehensive and strategic program of action to provide the children and pregnant and lactating mothers affected by disasters and other emergency situations with utmost support and assistance necessary for their immediate recovery and protection against all forms of violence, cruelty, discrimination, neglect, abuse, exploitation and other acts prejudicial to their interest, survival, development and well-being."}},{"id":"PH-H9269-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. – For the purposes of this Act, the following shall refer to:\n(a) Child – refers to a person below eighteen (18) years of age or those over but are unable to fully take care of themselves or protect themselves from abuse, neglect, cruelty, exploitation Or discrimination because of a physical or mental disability or condition as defined in Republic Act No. 7610 or the Special Protection of Children Against Abuse, Exploitation and Discrimination Act;\n(b) Child with Special Needs – refers to a child with a developmental or physical disability as defined in Republic Act No. 10165 or the Foster Care Act of 2012;\n(c) Child-Friendly Spaces – refer to spaces where communities create nurturing environments for children to engage in free and structured play, recreation, leisure and learning activities. The child-friendly space may provide health, nutrition, and psychosocial support, and other services or activities which will restore their normal functioning;\n(d) Civil Registry Documents – refer to all certificates, application forms, and certified true copies of legal instruments and court decrees concerning the acts and events affecting the civil status of persons which are presented before the Civil Registrar and are recorded in the Civil Registry;\n(e) Civil Society Organizations (CSOs) – as defined in Republic Act No.10121 or the Philippine Disaster Risk Reduction and Management Act of 2010, refer to non-state actors whose aims are neither to generate profits nor to seek governing power such as nongovernment organizations (NGOs), professional associations, foundations, independent research institutes, community-based organizations (CBOs), faith-based organizations, people’s organizations, social movements, and labor unions which are organized based on ethical, cultural, scientific, religious or philanthropic considerations;\n(f) Disasters – as defined in Republic Act No. 10121, refer to a serious disruption of the functioning of a community or a society involving widespread human, material, economic, or environmental losses and impacts, which exceeds the ability of the affected community or society to cope using its own resources. Disasters are often described as a result of the combination of: the exposure to a hazard; the conditions of vulnerability that are present; and insufficient capacity or measures to reduce or cope with the potential negative consequences. Disaster impacts may include loss of life, injury, disease and other negative effects on human, physical, mental and social well-being, together with damage to property, destruction of assets, loss of services, social and economic disruption, and environmental degradation;\n(g) Emergency – refers to unforeseen or sudden occurrence, especially danger, demanding immediate action as defined in Republic Act No. 10121;\n(h) Family Tracing and Reunification – refers to the process where disaster response teams reunite families separated by natural and human catastrophes by bringing together the child and family or previous care-provider for the purpose of establishing or reestablishing long-term care;\n(i) Hazard – refers to a dangerous phenomenon, substance, human activity or condition that may cause loss of life, injury or other health impacts, property damage, loss of livelihood and services, social and economic disruption, or environmental damage as defined in Republic Act No. 10121;\n(j) Orphans or Orphaned Children – refer to children who do not have a family and relatives who can assume responsibility for their care;\n(k) Separated Children – refer to children separated from both parents, or from their previous legal or usual primary caregiver, but not necessarily from other relatives. As a result, this may include children accompanied by other family members;\n(l) State of Calamity – refers to a condition involving mass casualty and/or major damages to property, disruption of means of livelihoods, roads, and normal way of life of people in the affected areas as a result of occurrence of natural or human-induced hazard as defined in Republic Act No. 10121;\n(m) Transitional Shelter – refers to structures temporarily constructed by the government intended for families affected by a disaster while awaiting transfer to permanent shelters; and\n(n) Unaccompanied Children – refer to children who have been separated from both parents and other relatives, and who are not being cared for by an adult who, by law or custom, is responsible for doing so."}},{"id":"PH-H9269-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Comprehensive Emergency Program for Children. – The Department of Social Welfare and Development (DSWD) shall formulate a Comprehensive Emergency Program for Children, hereinafter referred to as the Program, taking into consideration humanitarian standards for their protection. The Program shall be used as the basis for handling disasters and other emergency situations to protect children, pregnant and lactating mothers, and support their immediate recovery. This shall be implemented immediately after the declaration of a national or local state of calamity or occurrence of any other emergency situation.\nThe DSWD shall engage all relevant government agencies and stakeholders for the implementation of the Program. Local government units (LGUs) shall integrate the same in their development and Local Disaster Risk Reduction and Management (LDRRM) plans and budget.\nThe Program shall be gender-sensitive and have the following components:\nEstablishment of Evacuation Centers. – LGUs shall establish and identify safe locations as evacuation centers for children and families subject to the limitations found in Section 5 of this Act.\n(b) Establishment of Transitional Shelters for Orphaned, Separated, and Unaccompanied Children. – The National Housing Authority (NHA) shall, in coordination with the DSWD, the Department of Environment and Natural Resources (DENR), Department of Public Works and Highways (DPWH), Department of the Interior and Local Government (DILG), and LGUs of the areas declared under a state of calamity, immediately establish an option for transitional shelters, prioritizing vulnerable and marginalized groups including orphaned, separated, and unaccompanied children, and pregnant and lactating mothers. New transitional shelters, established pursuant to this Act, shall be designed with the following considerations: gender-specific emergency latrines, bathing cubicles, and hand washing facilities specifically designed for children. It shall provide mother and child-friendly spaces where children can take part in child activities. It shall also have provisions for maternal and newborn and infant care and rooms to protect, feed, provide personal care, and ensure the right to privacy. Existing transitional shelters shall be modified to the extent possible to comply with the abovementioned considerations.\n(c) Assurance for Immediate Delivery of Basic Necessities and Services. – The Program shall facilitate and ensure the immediate delivery of basic necessities and services specifically required by the affected children in different stages of development such as access to basic health services, food, water, nutrition, medicines, clothing, sanitary and hygiene kits, and other emergency needs such as blankets, mosquito nets, cooking ware and fiiel, and flashlights. The Program shall give priority to the specific health and nutrition needs of pregnant women, lactating mothers, newborn babies, children under five (5) years old and children with special needs.\n(d) Stronger Measures to Ensure the Safety and Security of Affected Children. – Under the Program, the Philippine National Police (PNP) shall, in coordination with the Armed Forces of the Philippines (AFP) and the DSWD, DILG, LGUs, Department of Education (DepED), Commission on Higher Education (CHED) and CSOs in the community, monitor and ensure the safety and the security of the affected children in the areas declared under a state of calamity and shall protect them against all forms of abuse and exploitation.\nUpon the declaration of a national and local state of calamity, the PNP and the DSWD, with the assistance of the AFP operating units in the area and local councils against trafficking and violence against women and their children, in accordance with existing laws, shall immediately heighten comprehensive measures and monitoring to prevent child trafficking, labor, and prostitution, including domestic and sexual violence, in the areas declared under a state of calamity.\nThe DSWD shall require all government agencies, LGUs, and CSOs which are tasked to provide any assistance or services to the affected children to adopt a child protection policy. The child protection policy shall include measures to deter and effectively respond to cases of violence, abuse, and exploitation of children.\nAll LGUs shall prioritize the establishment and functionality of the barangay violence against women and children (VAWC) desks. The VAWC desk shall serve as one of the key reporting and referral mechanism for cases of violence, abuse, and exploitation of children in the barangay diming all phases of emergency response and recovery.\nChildren shall be given priority during evacuation as a result of a disaster or other emergency situation. Existing CSOs in the community shall be tapped to look after the safety and well-being of children during evacuation operations. Measures shall be taken to ensure that children evacuated are accompanied by persons responsible for their safety and well-being.\n(e) Delivery of Health, Medical, and Nutrition Services. – Under the Program, the DOH, in coordination with the DSWD, LGUs, and CSOs in the community, shall provide the health, medical, and nutritional needs of children in the areas declared under a state of calamity, including psychosocial interventions for children in different stages of development.\n(f) Plan of Action for Prompt Resumption of Educational Services for Children. – The DepED, in coordination with the DSWD, DILG, and the concerned LGUs shall ensure the prompt resumption of educational services for all children, including early childhood care and development for children aged below five (5).\n(g) Establishment of Child-friendly Spaces. – The concerned LGU shall set up child-friendly spaces in every city or municipality declared under a state of calamity, as needed, based on the guidelines to be promulgated by the DSWD. In addition, LGUs shall coordinate with lead agencies and CSOs to effectively respond to the needs of the children in the area. Child-friendly spaces shall be made available throughout a crisis, from emergencies to recovery.\nIn case the concerned LGU cannot immediately respond due to the huge impact of disaster, the DSWD, together with the concerned national government agencies and in coordination with the CSOs and other stakeholders, as well as nearby LGUs, shall provide the necessary child care services and social protection of affected children.\n(h) Promotion of Children’s Rights. – The Program shall include activities and processes that will promote and uphold the rights of children by:\n(1) Providing child-centered training for all responders;\n(2) Ensuring that children are provided with adequate access to age-appropriate information on their roles and responsibilities and those of government agencies before, during, and after disasters and other emergency situations;\n(3) Providing an effective mechanism for training and meaningful participation of children in community disaster risk reduction program; and\n(4) Consulting with the affected children on their needs and priorities for post-disaster relief and recovery."}},{"id":"PH-H9269-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Evacuation Centers. – Only in cases where there is no other available place or structure which can be used as a general evacuation center may a school or child development center be used as an evacuation center.\nWhen a school or child development center is used as an evacuation center, gymnasiums, learning and activity centers, auditoriums and other open spaces shall be utilized first. Classrooms shall only be used as a last resort. The use of the school premises shall be as brief as possible. If the use is predicted to exceed fifteen (15) days, the affected LGU shall provide written documentation to the DepED and the DILG on the following:\n(a) The name and location of the school;\n(b) All alternative sites and proposal for final site selection;\n(c) Measures being implemented to prevent interference or disruption to the school and educational activities of children; and\n(d) Other particulars to be provided in the implementing rules and regulations of this Act.\nThe DepED, in coordination with the DPWH, shall continuously monitor and assess the condition of temporary learning spaces or other transitional and semi-permanent structures used as classrooms after a disaster, and if the use exceeds six (6) months after the declaration of a state of calamity, the regional DepED office shall conduct regular site inspections and shall certify to the Secretary of Education that such spaces are in good physical condition and sufficient to ensure the safety of the children and their environment."}},{"id":"PH-H9269-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Orphaned, Unaccompanied, or Separated Children. – The DSWD, upon consultation with relevant agencies, shall develop a minimum set of standards and guidelines for the Family Tracing Reunification System of orphaned, unaccompanied and separated children.\nOrphaned children, and unaccompanied or separated children whose families or relatives cannot he found or assessed to be incapable of providing proper care and protection shall be placed in a licensed or accredited residential care facility or with a foster family in accordance with Article 140 of the Child and Youth Welfare Code, or a community-based center. A registered social worker shall provide the needed case management and intervention."}},{"id":"PH-H9269-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"System of Restoring Civil Registry Documents. – To ensure that vital information pertaining to the personal circumstances of a child are adequately protected and available at all times, the Philippine Statistics Authority (PSA) shall develop a system for the restoration and reconstruction of civil registry documents that have been destroyed or declared lost or missing during a disaster or calamity.\nThe PSA shall submit a report on the number of restored or reconstructed documents to appropriate government agencies for effective monitoring and reporting and to ensure the continued access of the affected children to social services and facilitate the’ reunification of separated children with their families.\nThe PSA shall likewise develop a system for the registration of children born during a national or local state of calamity."}},{"id":"PH-H9269-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Training of Emergency Responders on Child Protection. – The National Disaster Risk Reduction and Management Council (NDRRMC) shall promote and conduct a child-responsive training program for all responders in the calamity area such as community and barangay leaders, community members, school personnel and other rescuers. The training program shall include the following:\n(a) Proper procedures and measures to assess the situation, safeguard and protect the affected children during and after emergencies and disasters; and\n(b) Appropriate training on psychosocial interventions for children in different stages of development who are victims of calamities.\nEach member agency shall include or mainstream child protection in their emergency response training to service providers."}},{"id":"PH-H9269-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Data Gathering, Monitoring, and Reporting. – The agencies mandated by this Act shall monitor and report on the implementation of services under the Program to be submitted jointly to Congress annually. The report shall include a specific section on pregnant women and children under five (5) years of age as a strategy to address the post-disaster nutrition needs of children under age five (5) and pregnant women.\nIn the aftermath of a national or local state of calamity, the collection and reporting of data for the Disaster Risk Reduction and Management Information System at all levels, as provided for in Republic Act No. 10121, shall be disaggregated by age, gender, ethnicity, and special needs. Such collected data shall be utilized to understand and respond better to the needs of children affected by disasters and calamities.\nWithin five (5) days from the declaration of a national state of calamity or as soon as practicable, the DSWD and the DILG shall jointly submit written documentation and report on their surveillance and monitoring under Section 4(d) to the appropriate committees of the Senate and the House of Representatives."}},{"id":"PH-H9269-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Appropriations. – The amount necessary for the initial implementation of this Act shall be charged against the current appropriations of the DSWD, Office of Civil Defense (OCD), DepED, DOH, Department of National Defense (DND) and PSA. Thereafter, the amount needed for the continued implementation of this Act shall be included in the annual General Appropriations Act. For LGUs, the implementation of the programs shall be charged against the Local Disaster Risk Reduction and Management Fund (LDRRMF)."}},{"id":"PH-H9269-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Implementing Rules and Regulations. – Within ninety (90) days from the effectivity of this Act, the DSWD, in consultation and coordination with the DND, OCD, DOH, DepED, DILG, PNP, AFP and child-focused CSOs shall promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H9269-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Interpretation Clause. – The provisions of this Act and its implementing rules and regulations shall be liberally construed in favor of the best interest of the child."}},{"id":"PH-H9269-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. – If any provision or part of this Act is declared invalid or unconstitutional, the remaining parts or provisions not affected shall remain in full force and effect."}},{"id":"PH-H9269-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause. – All laws, executive orders, presidential decrees, rules and regulations or parts thereof inconsistent with any provision of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H9269-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper £f general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Mandating the Provision of Emergency Relief and Protection for Children Before, During, and After Disasters and Other Emergency Situations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9270"] = {"id":"PH-H9270","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10822_2016.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":"授予 Pipol 宽带与电信公司在菲律宾全境建设、安装、设立、运营和维护电信系统的特许经营权法案","en":"An Act Granting the Pipol Broadband and Telecommunications Corporation a Franchise to Construct, Install, Establish, Operate and Maintain Telecommunications Systems Throughout the Philippines","orig":"An Act Granting the Pipol Broadband and Telecommunications Corporation a Franchise to Construct, Install, Establish, Operate and Maintain Telecommunications Systems Throughout the Philippines","vi":"Đạo luật cấp quyền khai thác cho Pipol Broadband and Telecommunications Corporation để xây dựng, lắp đặt, vận hành và duy trì hệ thống viễn thông trên toàn lãnh thổ Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Pipol Broadband and Telecommunications Corporation เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบโทรคมนาคมทั่วประเทศฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Pipol Broadband and Telecommunications Corporation untuk membangun, memasang, mengoperasikan, dan memelihara sistem telekomunikasi di seluruh wilayah Filipina","ms":"Akta memberikan francais kepada Pipol Broadband and Telecommunications Corporation untuk membina, memasang, mengendalikan dan menyelenggara sistem telekomunikasi di seluruh wilayah Filipina"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 10822","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-18","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10822_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9270-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, there is hereby granted to Pipol Broadband and Telecommunications Corporation, hereunder referred to as the grantee, its successors or assignees, a franchise to construct, install, establish, operate, and maintain for commercial purposes and in the public interest, throughout the Philippines and between the Philippines and other countries and territories, wire and/or wireless telecommunications systems including, but not limited to, mobile cellular, paging, fiber optics, satellite transmit and receive systems, switches, and their value-added services such as, but not limited to, transmission of voice, data, facsimile, control signs, audio and video, information services, and all other telecommunications systems technologies as are at present available or will be made available through technological advances or innovations in the future; and/or construct, acquire, lease, and operate or manage transmitting and receiving stations, lines, cables, or systems as are convenient or essential to efficiently carry out the purpose of this franchise."}},{"id":"PH-H9270-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee’s services and/or the availability thereof."}},{"id":"PH-H9270-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission (NTC) a Certificate of Public Convenience and Necessity or the appropriate permits and licenses for the construction, installation and operation of its telecommunications systems/facilities. In issuing the certificate, the NTC shall have the power to impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications system. The NTC shall have the authority to regulate the construction and operation of its ‘ telecommunications systems. The grantee shall not use any frequency in the radio spectrum without authorization from the NTC. Such certificate shall state the areas covered and the date the grantee shall commence the service. The NTC, however, shall not unreasonably withhold or delay the grant of any such authority, permits, or licenses."}},{"id":"PH-H9270-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Excavation and Restoration Works. – For the purpose of erecting and maintaining poles or other supports for the said wires or other conductors for the purpose of laying and maintaining underground wires, cables, or other conductors, it shall be lawful for the grantee, its successors or assignees, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government unit (LGU) concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, roads, highways, streets, lanes, alleys, avenues, sidewalks or bridges of said provinces, cities and/or municipalities: Provided, however, That a public place, road, highway, street, lane, alley, avenue, sidewalk or bridge disturbed, altered, or changed by reason of erection of poles or other supports or the underground laying of wires, other conductors, or conduits shall be repaired and replaced in workmanlike manner by the grantee, its successors or assignees, in accordance with the standards set by the DPWH or the LGU concerned. Should the grantee, its successors or assignees, after the ten (10)-day notice from the said authority, fail, refuse or neglect to repair or replace any part of public place, road, highway, street, lane, alley, avenue, sidewalk or bridge altered, changed or disturbed by the said grantee, its successors or assignees, then the DPWH or the LGU concerned shall have the right to have the same repaired and placed in good order and condition at double expense to be charged against the grantee, its successors or assignees."}},{"id":"PH-H9270-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. – The grantee shall conform to the ethics of honest enterprise and not use its stations or facilities for obscene or indecent transmission, or for dissemination of deliberately false information, or willful misrepresentation, or assist in subversive or treasonable acts.\nThe grantee shall provide basic or enhanced telephone service in any city and/or municipality in the Philippines where it has an approved Certificate of Public Convenience and Necessity for the establishment, operation and maintenance of a local exchange service, without discrimination to any applicant therefor, in the order of the date of their applications, up to the limit of the capacity of its local telephone exchange and, should the demand for the telephone service at any time increase beyond the capacity thereof the grantee shall increase the same to meet such demand: Provided, That in case the total demand to be satisfied by the expansion is less than the smallest viable local exchange available in the market as determined by the NTC, the grantee shall not be obliged to furnish such service unless the applicant for telephone service defrays the actual expenses for the installation of the telecommunications apparatus necessary for such services and in such case, the NTC may extend the time within which the grantee shall furnish such service.\nThe grantee shall operate and maintain all its stations, lines, cables, systems, and equipment for the transmission and reception of messages, signals, and pulses in a satisfactory manner at all times and, as far as economical and practicable, modify, improve, or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology."}},{"id":"PH-H9270-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rates for Services. – The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as nonregulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the NTC or its legal successor. The rates to be charged by the grantee shall be unbundled, separable, and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H9270-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order to temporarily take over and operate the stations, transmitters, facilities, or equipment of the grantee; to temporarily suspend the operation of any station, transmitter, facility, or equipment in the interest of public safety, security and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of the stations, transmitters, facilities, or equipment during the period when these shall be so operated.\nThe radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn any time after due process."}},{"id":"PH-H9270-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Term of Franchise. – This franchise shall be in effect for a period of twenty-five (25) years from the date of effectivity of this Act, unless sooner cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to comply with any of the following conditions:\n(a) Commence operations within one (1) year from the approval of its operating permit by the NTC;\n(b) Commence operations within three (3) years from the effectivity of this Act; and\n(c) Operate continuously for two (2) years."}},{"id":"PH-H9270-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void. ‘"}},{"id":"PH-H9270-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Bond. – The grantee shall file a bond with the NTC in the amount that it shall determine to guarantee compliance with and fulfillment of the conditions under which this franchise is granted. If after three (3) years from the date of the approval of its permit by the NTC, the grantee shall have fulfilled the conditions, the bond shall be cancelled by the NTC. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H9270-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Right of Interconnection. – The grantee is hereby authorized to connect or demand connection of its telecommunications systems to other telecommunications systems installed, operated and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public, under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to the review and modification of the NTC."}},{"id":"PH-H9270-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Gross Receipts. – The grantee, its successors or assignees, shall keep a separate account of the gross receipts of the business transacted by it and shall furnish the Commission on Audit (COA) and the National Treasury a copy of such account not later than the thirty-first (31st) day of January of each year for the preceding twelve (12) months."}},{"id":"PH-H9270-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Books and Accounts. – The books and accounts of the grantee, its successors or assignees, shall always be open to the inspection of the COA and its duly authorized representatives. It shall be the duty of the grantee to submit to the COA two (2) copies of the quarterly reports on the gross receipts, the net profits, and the general condition of the business."}},{"id":"PH-H9270-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Warranty in Favor of the National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines free from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, transmitters, facilities or equipment of the grantee."}},{"id":"PH-H9270-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. – The grantee shall not sell, lease, transfer, grant the usufruct of, nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation, or other commercial or legal entity, nor merge with any other corporation or entity, nor shall transfer the controlling interest of the grantee, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation, or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any sale, lease, transfer, grant of usufruct, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger, or transfer of controlling interest of the grantee, within sixty (60) days after the completion of the said transaction: Provided, further, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred, or assigned shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H9270-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations: Provided, That in cases where public offer of shares is not applicable, establishment of cooperatives and other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9270-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the term of the franchise. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9270-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Penalty Clause. – Failure to submit the requisite annual report to Congress shall be penalized with a fine of five’ hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from the delinquent franchise grantee separate from the reportorial penalties imposed by the NTC. All proceeds from said fines or penalties shall accrue to the monitoring fund of the NTC in line with its supervisory and regulatory functions."}},{"id":"PH-H9270-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Equality Clause. – Any advantage, favor, privilege, exemption, or immunity granted under other existing franchise, or which may hereafter be granted, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, however, That the foregoing shall neither apply to nor affect provisions of telecommunications franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise."}},{"id":"PH-H9270-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9270-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Repeatability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H9270-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Pipol Broadband and Telecommunications Corporation a Franchise to Construct, Install, Establish, Operate and Maintain Telecommunications Systems Throughout the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9271"] = {"id":"PH-H9271","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10823_2016.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将新比斯开省Kasibu市镇Pudi描笼涯由技术教育与技能发展署（TESDA）管理的Kasibu国立农业学校更名为新比斯开理工学院的法案","en":"An Act Changing the Name of Kasibu National Agricultural School Being Administered By the Technical Education and Skills Development Authority (TESDA) in Barangay Pudi, Municipality of Kasibu, Province of Nueva Vizcaya to Nueva Vizcaya Polytechnic Institute","orig":"An Act Changing the Name of Kasibu National Agricultural School Being Administered By the Technical Education and Skills Development Authority (TESDA) in Barangay Pudi, Municipality of Kasibu, Province of Nueva Vizcaya to Nueva Vizcaya Polytechnic Institute","vi":"Đạo luật đổi tên Cơ quan Kasibu National Agricultural School Being Administered By the Technical Education and Skills Development tại Barangay Pudi, Đô thị Kasibu, Tỉnh Nueva Vizcaya thành Học viện Nueva Vizcaya Polytechnic","th":"พระราชบัญญัติเปลี่ยนชื่อองค์กร Kasibu National Agricultural School Being Administered By the Technical Education and Skills Development ในบารังไกย์ Pudi เทศบาล Kasibu จังหวัด Nueva Vizcaya เป็น สถาบัน Nueva Vizcaya Polytechnic","id":"Undang-Undang mengubah nama Otoritas Kasibu National Agricultural School Being Administered By the Technical Education and Skills Development di Barangay Pudi, Kotamadya Kasibu, Provinsi Nueva Vizcaya menjadi Institut Nueva Vizcaya Polytechnic","ms":"Akta menukar nama Pihak Berkuasa Kasibu National Agricultural School Being Administered By the Technical Education and Skills Development di Barangay Pudi, Perbandaran Kasibu, Wilayah Nueva Vizcaya kepada Institut Nueva Vizcaya Polytechnic"},"level":"law","status":"active","topics":["administrative","education","environment"],"docNumber":"Republic Act No. 10823","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10823_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9271-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Kasibu National Agricultural School being administered by the Technical Education and Skills Development Authority (TESDA) in Barangay Pudi, Municipality of Kasibu, Province of Nueva Vizcaya is hereby changed to Nueva Vizcaya Polytechnic Institute."}},{"id":"PH-H9271-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Kasibu National Agricultural School Being Administered By the Technical Education and Skills Development Authority (TESDA) in Barangay Pudi, Municipality of Kasibu, Province of Nueva Vizcaya to Nueva Vizcaya Polytechnic Institute","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9272"] = {"id":"PH-H9272","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10824_2016.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将马斯巴特省Milagros市镇通称马斯巴特渔业学校的Milagros渔业学校更名为马斯巴特渔业与技术学院的法案","en":"An Act Renaming the Milagros School of Fisheries, Popularly Known as the Masbate School of Fisheries in the Municipality of Milagros, Province of Masbate, as the Masbate Institute of Fisheries and Technology","orig":"An Act Renaming the Milagros School of Fisheries, Popularly Known as the Masbate School of Fisheries in the Municipality of Milagros, Province of Masbate, as the Masbate Institute of Fisheries and Technology","vi":"Đạo luật đổi tên Trường Milagros Fisheries, Popularly Known thành Học viện Thủy sản Công nghệ Masbate School of Fisheries in the Municipality of Milagros, Province of Masbate, as the Masbate","th":"พระราชบัญญัติเปลี่ยนชื่อโรงเรียน Milagros Fisheries, Popularly Known เป็น สถาบันประมงเทคโนโลยี Masbate School of Fisheries in the Municipality of Milagros, Province of Masbate, as the Masbate","id":"Undang-Undang mengubah nama Sekolah Milagros Fisheries, Popularly Known menjadi Institut Perikanan Teknologi Masbate School of Fisheries in the Municipality of Milagros, Province of Masbate, as the Masbate","ms":"Akta menukar nama Sekolah Milagros Fisheries, Popularly Known kepada Institut Perikanan Teknologi Masbate School of Fisheries in the Municipality of Milagros, Province of Masbate, as the Masbate"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 10824","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10824_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9272-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Milagros School of Fisheries, popularly known as the Masbate School of Fisheries, which is under the direct supervision of the Technical Education and Skills Development Authority (TESDA) and located in the Municipality of Milagros, Province of Masbate is hereby renamed as the Masbate Institute of Fisheries and Technology, hereinafter referred to as the Institute."}},{"id":"PH-H9272-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All assets, real and personal, personnel and records of the Milagros School of Fisheries, as well as liabilities or obligations, are hereby transferred to the Masbate Institute of Fisheries and Technology upon the effectivity of this Act. All plantilla positions shall be retained, with the rights and security of tenure of faculty members and personnel therein employed under existing laws prior to the effectivity of this Act."}},{"id":"PH-H9272-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws, decrees, executive orders, rules and regulations or parts thereof which are inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H9272-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renaming the Milagros School of Fisheries, Popularly Known as the Masbate School of Fisheries in the Municipality of Milagros, Province of Masbate, as the Masbate Institute of Fisheries and Technology","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9273"] = {"id":"PH-H9273","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10825_2016.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"在北苏里高省苏里高市与 Del Carmen 市镇设立多品种海洋孵化场并为其拨款的法案","en":"An Act Establishing Multi-Species Marine Hatcheries in Surigao City and the Municipality of Del Carmen in the Province of Surigao Del Norte and Appropriating Funds Therefor","orig":"An Act Establishing Multi-Species Marine Hatcheries in Surigao City and the Municipality of Del Carmen in the Province of Surigao Del Norte and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10825","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-19","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10825_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9273-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the Bureau of Fisheries and Aquatic Resources of the Department of Agriculture (BFAR-DA), multi-species marine hatcheries in Surigao City and the Municipality of Del Carmen in the Province of Surigao del Norte."}},{"id":"PH-H9273-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Within two (2) years after the construction of the multi-species marine hatcheries, the BFAR shall, through a memorandum of agreement, transfer their management to the local government units concerned. It shall implement a training and phasing-in program for local government personnel on the management and operation of the multi-species marine hatcheries."}},{"id":"PH-H9273-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Agriculture shall include in the Departments programs the establishment of the multi-species marine hatcheries, the funding of which shall be included in the annual General Appropriations Act. The local government units concerned shall set aside funds from any available local revenue to fund their management and operation."}},{"id":"PH-H9273-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Agriculture shall issue the rules and regulations on the supervision and monitoring, and the transfer or withdrawal, by the BFAR of the multi-species marine hatcheries."}},{"id":"PH-H9273-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15)”days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing Multi-Species Marine Hatcheries in Surigao City and the Municipality of Del Carmen in the Province of Surigao Del Norte and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9274"] = {"id":"PH-H9274","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10826_2016.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Kalamansig市","en":"An Act Establishing a Multi-Species Marine Nursery in the Municipality of Kalamansig, Province of Sultan Kudarat and Appropriating Funds Therefor","orig":"An Act Establishing a Multi-Species Marine Nursery in the Municipality of Kalamansig, Province of Sultan Kudarat and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10826","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-19","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10826_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9274-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Bureau of Fisheries and Aquatic Resources of the Department of Agriculture (BFAR-DA), a multi-species marine nursery in the Municipality of Kalamansig, Province of Sultan Kudarat."}},{"id":"PH-H9274-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Agriculture shall include in the Department’s programs the establishment of the multi-species marine nursery, preferably in the abandoned, undeveloped, or underutilized fishponds covered by fishpond lease agreements in the Municipality of Kalamansig, Province of Sultan Kudarat, the funding of which shall be included in the annual General Appropriations Act. The local government units concerned shall set aside funds from any available local revenue in an amount deemed appropriate for its management and operation."}},{"id":"PH-H9274-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Within two (2) years after the establishment of the multi-species marine nursery, the BFAR shall, through a memorandum of agreement, transfer its management to the municipality or the community where it will be located. It shall implement a training and phasing-in program for the management and operation of the multi-species marine nursery."}},{"id":"PH-H9274-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Agriculture shall issue the rules and regulations on the supervision and monitoring, and the transfer or withdrawal, by the BFAR of the multi-species marine nursery."}},{"id":"PH-H9274-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132"};
  FT["PH-H9275"] = {"id":"PH-H9275","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10827_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将帕拉尼亚克市第二区陆运署（LTO）卫星办公室改设为陆运署正式区办公室并为此拨款的法案","en":"An Act Converting the Satellite Office of the Land Transportation Office (LTO) in District 2, Parañaque City Into a Regular LTO District Office and Appropriating Funds Therefor","orig":"An Act Converting the Satellite Office of the Land Transportation Office (LTO) in District 2, Parañaque City Into a Regular LTO District Office and Appropriating Funds Therefor","vi":"Đạo luật chuyển đổi Văn phòng vệ tinh Land Transportation Office thành Văn phòng Khu vực Regular LTO tại Quận 2, Quận Parañaque City, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติเปลี่ยนสถานะสำนักงานดาวเทียม Land Transportation Office เป็น สำนักงานเขต Regular LTO ในเขต 2 เขต Parañaque City และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang mengubah status Kantor Satelit Land Transportation Office menjadi Kantor Distrik Regular LTO di Distrik 2, Distrik Parañaque City, dan mengalokasikan dana untuk itu","ms":"Akta menukar status Pejabat Satelit Land Transportation Office kepada Pejabat Daerah Regular LTO di Daerah 2, Daerah Parañaque City, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10827","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10827_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9275-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Land Transportation Office (LTO) Satellite Office in District 2, Parañaque City is hereby converted into a regular LTO district office."}},{"id":"PH-H9275-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall include in the Department’s program the operationalization of a Regular LTO District Office in District 2, Parañaque City, the initial funding of which shall be charged against the current year’s appropriation of the Satellite Office located in District 2, Parañaque City. Thereafter, such sums as may be necessary for the continued operation of the Regular LTO District Office shall be included in the annual General Appropriations Act."}},{"id":"PH-H9275-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Satellite Office of the Land Transportation Office (LTO) in District 2, Parañaque City Into a Regular LTO District Office and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9276"] = {"id":"PH-H9276","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10828_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在萨兰加尼省设立陆运署正式区办公室并为此拨款的法案","en":"An Act Establishing a Regular District Office of the Land Transportation Office in the Province of Sarangani and Appropriating Funds Therefor","orig":"An Act Establishing a Regular District Office of the Land Transportation Office in the Province of Sarangani and Appropriating Funds Therefor","vi":"Đạo luật thành lập một Văn phòng Khu vực Chính quy Land Transportation Office tại Tỉnh Sarangani, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งสำนักงานเขตปกติ Land Transportation Office ในจังหวัด Sarangani และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk sebuah Kantor Distrik Reguler Land Transportation Office di Provinsi Sarangani, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan sebuah Pejabat Daerah Biasa Land Transportation Office di Wilayah Sarangani, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10828","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10828_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9276-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established in the Municipality of Alabel, Province of Sarangani a Regular District Office of the Land Transportation Office (LTO)."}},{"id":"PH-H9276-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall include in the Department’s program the operationalization of the Regular District Office of the LTO in the Municipality of Alabel, Province of Sarangani, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9276-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a Regular District Office of the Land Transportation Office in the Province of Sarangani and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9277"] = {"id":"PH-H9277","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10829_2016.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在帕赛市设立国立科学中学，名称为帕赛市国立科学中学，并为此拨款的法案","en":"An Act Establishing a National Science High School in the City of Pasay to Be Known as Pasay City National Science High School and Appropriating Funds Therefor","orig":"An Act Establishing a National Science High School in the City of Pasay to Be Known as Pasay City National Science High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông khoa học quốc gia tại Thành phố Pasay được biết đến với tên gọi Trường trung học phổ thông khoa học quốc gia Pasay City","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมวิทยาศาสตร์แห่งชาติในเมือง Pasay ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมวิทยาศาสตร์แห่งชาติ Pasay City","id":"Undang-Undang mendirikan Sekolah Menengah Sains Nasional di Kota Pasay dikenal sebagai Sekolah Menengah Sains Nasional Pasay City","ms":"Akta menubuhkan Sekolah Menengah Sains Kebangsaan di Bandaraya Pasay dikenali sebagai Sekolah Menengah Sains Kebangsaan Pasay City"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10829","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-11","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10829_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9277-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National Science High School. – There is hereby established, under the supervision of the Department of Education, a national science high school in the City of Pasay to be known as Pasay City National Science High School."}},{"id":"PH-H9277-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Pasay City National Science High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9277-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. – The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H9277-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a National Science High School in the City of Pasay to Be Known as Pasay City National Science High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9278"] = {"id":"PH-H9278","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10830_2016.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将伊洛伊洛市 Mandurriao 区 Bakhaw 描笼涯的 Bakhaw 小学改设为名为 Bakhaw 综合学校的综合学校并为其拨款","en":"An Act Converting the Bakhaw Elementary School in Barangay Bakhaw, District of Mandurriao, Iloilo City Into An Integrated School to Be Known as Bakhaw Integrated School and Appropriating Funds Therefor","orig":"An Act Converting the Bakhaw Elementary School in Barangay Bakhaw, District of Mandurriao, Iloilo City Into An Integrated School to Be Known as Bakhaw Integrated School and Appropriating Funds Therefor","vi":"Đạo luật chuyển đổi Bakhaw Elementary School thành Bakhaw Integrated School","th":"พระราชบัญญัติเปลี่ยนสถานะ Bakhaw Elementary School เป็น Bakhaw Integrated School","id":"Undang-Undang mengubah Bakhaw Elementary School menjadi Bakhaw Integrated School","ms":"Akta menukar Bakhaw Elementary School kepada Bakhaw Integrated School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10830","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-11","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10830_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9278-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Bakhaw Elementary School in Barangay Bakhaw, District of Mandurriao, Iloilo City is hereby converted into an integrated school to be known as Bakhaw Integrated School."}},{"id":"PH-H9278-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, assets, liabilities and records of the Bakhaw Elementary School are hereby transferred to and absorbed by the Bakhaw Integrated School."}},{"id":"PH-H9278-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department’s program the operationalization of the Bakhaw Integrated School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9278-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H9278-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Bakhaw Elementary School in Barangay Bakhaw, District of Mandurriao, Iloilo City Into An Integrated School to Be Known as Bakhaw Integrated School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9279"] = {"id":"PH-H9279","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10831_2016.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Bayog市","en":"An Act Establishing a National High School in Barangay Balukbahan, Municipality of Bayog, Province of Zamboanga Del Sur to Be Known as Balukbahan National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Balukbahan, Municipality of Bayog, Province of Zamboanga Del Sur to Be Known as Balukbahan National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Balukbahan, Thị trấn Bayog, Tỉnh Zamboanga Del Sur được biết đến với tên gọi Trường trung học phổ thông quốc gia Balukbahan","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Balukbahan, เทศบาล Bayog, จังหวัด Zamboanga Del Sur ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Balukbahan","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Balukbahan, Kotamadya Bayog, Provinsi Zamboanga Del Sur dikenal sebagai Sekolah Menengah Atas Nasional Balukbahan","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Balukbahan, Perbandaran Bayog, Wilayah Zamboanga Del Sur dikenali sebagai Sekolah Menengah Kebangsaan Balukbahan"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10831","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-11","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10831_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9279-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established, under the supervision, of the Department of Education, a national high school in Barangay Balukbahan, Municipality of Bayog, Province of Zamboanga del Sur to be known as Balukbahan National High School."}},{"id":"PH-H9279-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education shall immediately include in the Department’s program the operationalization of the Balukbahan National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9279-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H9279-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p132"};
